import { Meta, StoryObj } from "@storybook/react";
import { Stepper } from "./stepper";
import { useState } from "react";

const meta = {
  title: "Primitives/Stepper",
  component: Stepper,
  argTypes: {},
  render: function StoryComponent(args) {
    const [currentStep, setCurrentStep] = useState<number>(args.currentStep || 1);
    const generateNavigateCallbacks = (length: number, setCurrentStep: (step: number) => void): Array<() => void> => {
      return Array.from({ length }, (_, index) => () => setCurrentStep(index + 1));
    };
    const modifiedOnNavigate = generateNavigateCallbacks(args.onNavigate.length, setCurrentStep);
    return (
      <div>
        <Stepper
          key="stpper"
          heading={args.heading}
          headingComponent={args.headingComponent}
          currentStep={currentStep}
          onNavigate={modifiedOnNavigate}
        />
      </div>
    );
  },
} satisfies Meta<typeof Stepper>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Primary: Story = {
  args: {
    heading: "Stepper",
    headingComponent: "h1",
    currentStep: 1,
    onNavigate: [
      () => console.log("Navigated to Step 1"),
      () => console.log("Navigated to Step 2"),
      () => console.log("Navigated to Step 3"),
    ],
  },
};

